
import React, { forwardRef, useEffect, useRef, useState, useMemo } from 'react';
import './PlacaFardo.css';

const PlacaFardo = forwardRef(({ titulo, fardo, precoInicial, precoReal, precoCentavos, dataInicial, dataFinal }, ref) => {

    const tituloFardoRef = useRef(null);
    const containerFardoRef = useRef(null);
    const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte
    // Ajusta o font-size do título
    console.log("##### PrecoInicial #######"+precoInicial);
    useEffect(() => {
      const ajustarFonte = () => {
        const tituloE1 = tituloFardoRef.current;
        const containerE1 = containerFardoRef.current;

        if (!tituloE1 || !containerE1) return;

        let size = 200;
        tituloE1.style.fontSize = `${size}px`;

        while (tituloE1.scrollHeight - containerE1.clientHeight > 0) {
            size -= 1;
            tituloE1.style.fontSize = `${size}px`;
          }

        setFontSize(size);
      };

      ajustarFonte();
    }, [titulo]); 

    const fontSizeReal = useMemo(() => {
    if (!precoReal) return '450px';
    const length = precoReal.toString().length;

    if (length <= 2) return '450px';   // 1 ou 2 dígitos
    if (length === 3) return '400px';  // 3 dígitos
    if (length === 4) return '300px';  // 4 dígitos
    return '220px';                    // 5 ou mais dígitos
  }, [precoReal]);

  return (
    <div ref={ref} className="placa-fardo">
        <span className="sloganFardo">OFERTA</span>
        <div className="corpoFardo">
          <div
              className="tituloFardoContainer"
              ref={containerFardoRef}
              style={{
                width: '100%',
                height: '52mm', // defina altura conforme desejado
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                overflow: 'hidden',
                textAlign: 'center',
              }}
          >
            <span 
              ref={tituloFardoRef}
              className="tituloFardo"
              style={{
                fontSize: `${fontSize}px`,
                lineHeight: 1.1,
                wordBreak: 'break-word',
              }}
            >
              {titulo}
            </span>
          </div>
            {fardo>1 && <div className='classFardo'><span className='fardo'>&nbsp;Und por R$ <b>{precoInicial}</b>.</span> <span className='fardo'>Fardo com&nbsp;<b>{fardo}</b> &nbsp;por:</span></div>}
            <div className='precoFardo'>
              <span 
                className="precoFardoReal"
                style={{ fontSize: fontSizeReal }}
              >
                {precoReal} 
              </span>
              <span className="precoFardoCentavos">,{precoCentavos}</span>
            </div>    
        </div>
        {dataInicial === dataFinal ? (
            <span className='footerFardo'>Oferta válida para o dia {dataFinal}.</span>
          ) : (
            <span className='footerFardo'>Oferta válida de {dataInicial} até {dataFinal}.</span>
          )
        }
    </div>
  );
});

export default PlacaFardo; 