
import React, { forwardRef, useEffect, useRef, useState, useMemo } from 'react';
import './PlacaMaisSuino.css';

const PlacaMaisSuino = forwardRef(({ titulo, precoInicial, precoReal, precoCentavos, dataInicial, dataFinal }, ref) => {

    const tituloSuinoRef = useRef(null);
    const containerSuinoRef = useRef(null);
    const [fontSize, setFontSize] = useState(100); // tamanho inicial da fonte

      // Ajusta o font-size do título
      useEffect(() => {
        const ajustarFonte = () => {
          const tituloE1 = tituloSuinoRef.current;
          const containerE1 = containerSuinoRef.current;

          if (!tituloE1 || !containerE1) return;

          let size = 200;
          tituloE1.style.fontSize = `${size}px`;

          while (tituloE1.scrollHeight - containerE1.clientHeight > 0) {
              size -= 1;
              tituloE1.style.fontSize = `${size}px`;
            }

          setFontSize(size);
        };

        ajustarFonte();
      }, [titulo]);

     const fontSizeRealChurrasco = useMemo(() => {
            if (!precoReal) return '640px';
            const length = precoReal.toString().length;
            console.log(length);
        
            if (length <= 2) return '600px';   // 1 ou 2 dígitos
            if (length === 3) return '450px';  // 3 dígitos
            if (length === 4) return '400px';  // 4 dígitos
            return '320px';                    // 5 ou mais dígitos
          }, [precoReal]);
          

  return (
    <div ref={ref} className="placa-maischurrasco">
        <span className="sloganMaisSuino">MAIS SUÍNO</span>
        <div className="corpoMaisChurrasco">
          <div
              className="tituloMaisChurrascoContainer"
              ref={containerSuinoRef}
              style={{
                width: '100%',
                height: '52mm', // defina altura conforme desejado
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                overflow: 'hidden',
                textAlign: 'center',
              }}
          >
            <span 
              ref={tituloSuinoRef}
              className="tituloMaisChurrasco"
              style={{
                fontSize: `${fontSize}px`,
                lineHeight: 1.1,
                wordBreak: 'break-word',
              }}
            >
              {titulo}
            </span>
          </div>
            {(precoInicial && precoInicial !== "-") && <span className='cifraoMaisSuino'>&nbsp;De&nbsp;<b>{precoInicial} </b>. Por R$</span>}
            {!precoInicial && <span className='cifraoMaisSuino'>&nbsp; R$</span>}
            <div className='precoMaisChurrasco'>

              <span 
                className="precoMaisChurrascoReal"
                style={{ fontSize: fontSizeRealChurrasco }}
              >
                {precoReal} 
              </span>
              <span className="precoMaisChurrascoCentavos">,{precoCentavos}</span>
            </div>    
        </div>
        {dataInicial === dataFinal ? (
            <span className='footerMaisChurrasco'>Oferta válida para o dia {dataFinal}.</span>
          ) : (
            <span className='footerMaisChurrasco'>Oferta válida de {dataInicial} até {dataFinal}.</span>
          )
        }
    </div>
  );
});

export default PlacaMaisSuino;